additionalExercises.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Node { int& live; std::shared_ptr<Node> child; std::weak_ptr<Node> parent; explicit Node(int& n): live(n) { ++live; } ~Node() { --live; } };
int solve(int a, int b) { int live = 0, saved; { auto root = std::make_shared<Node>(live); auto child = std::make_shared<Node>(live); root->child = child; child->parent = root; saved = a + b; } return live == 0 ? saved : -9999; }
